Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
rxrpc: fix oversized RESPONSE authenticator length check

rxgk_verify_response() decodes auth_len from the packet and is supposed
to verify that it fits in the remaining bytes. The existing check is
inverted, so oversized RESPONSE authenticators are accepted and passed
to rxgk_decrypt_skb(), which can later reach skb_to_sgvec() with an
impossible length and hit BUG_ON(len).

Decoded from the original latest-net reproduction logs with
scripts/decode_stacktrace.sh:

RIP: __skb_to_sgvec()
  [net/core/skbuff.c:5285 (discriminator 1)]
Call Trace:
 skb_to_sgvec() [net/core/skbuff.c:5305]
 rxgk_decrypt_skb() [net/rxrpc/rxgk_common.h:81]
 rxgk_verify_response() [net/rxrpc/rxgk.c:1268]
 rxrpc_process_connection()
   [net/rxrpc/conn_event.c:266 net/rxrpc/conn_event.c:364
    net/rxrpc/conn_event.c:386]
 process_one_work() [kernel/workqueue.c:3281]
 worker_thread()
   [kernel/workqueue.c:3353 kernel/workqueue.c:3440]
 kthread() [kernel/kthread.c:436]
 ret_from_fork() [arch/x86/kernel/process.c:164]

Reject authenticator lengths that exceed the remaining packet payload.

Fixes: 9d1d2b59341f ("rxrpc: rxgk: Implement the yfs-rxgk security class (GSSAPI)")
Signed-off-by: Keenan Dong <keenanat2000@gmail.com>
Signed-off-by: David Howells <dhowells@redhat.com>
cc: Marc Dionne <marc.dionne@auristor.com>
cc: Simon Horman <horms@kernel.org>
cc: Willy Tarreau <w@1wt.eu>
cc: linux-afs@lists.infradead.org
cc: stable@kernel.org
Link: https://patch.msgid.link/20260408121252.2249051-14-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In the function rxgk_verify_response(), the length check for the authenticator field was inverted. The condition `if (auth_len < len)` should have been `if (auth_len > len)` to reject oversized authenticators that exceed the remaining packet payload. This logic error allowed oversized RESPONSE authenticators to be accepted, which later triggered a BUG_ON in __skb_to_sgvec() when an impossible length was passed to skb_to_sgvec() via rxgk_decrypt_skb().

Here is the patch:
  */
 static int rxgk_verify_response(struct rxrpc_connection *conn,
 				struct sk_buff *skb)
 {
 	const struct krb5_enctype *krb5;
 	struct rxrpc_key_token *token;
 	struct rxrpc_skb_priv *sp = rxrpc_skb(skb);
 	struct rxgk_response rhdr;
 	struct rxgk_context *gk;
 	struct key *key = NULL;
 	unsigned int offset = sizeof(struct rxrpc_wire_header);
 	unsigned int len = skb->len - sizeof(struct rxrpc_wire_header);
 	unsigned int token_offset, token_len;
 	unsigned int auth_offset, auth_len;
 	__be32 xauth_len;
 	int ret, ec;

 	_enter("{%d}", conn->debug_id);

 	/* Parse the RXGK_Response object */
 	if (sizeof(rhdr) + sizeof(__be32) > len)
 		goto short_packet;

 	if (skb_copy_bits(skb, offset, &rhdr, sizeof(rhdr)) < 0)
 		goto short_packet;
 	offset	+= sizeof(rhdr);
 	len	-= sizeof(rhdr);

 	token_offset	= offset;
 	token_len	= ntohl(rhdr.token_len);
 	if (xdr_round_up(token_len) + sizeof(__be32) > len)
 		goto short_packet;

 	trace_rxrpc_rx_response(conn, sp->hdr.serial, 0, sp->hdr.cksum, token_len);

 	offset	+= xdr_round_up(token_len);
 	len	-= xdr_round_up(token_len);

 	if (skb_copy_bits(skb, offset, &xauth_len, sizeof(xauth_len)) < 0)
 		goto short_packet;
 	offset	+= sizeof(xauth_len);
 	len	-= sizeof(xauth_len);

 	auth_offset	= offset;
 	auth_len	= ntohl(xauth_len);
-	if (auth_len < len)
+	if (auth_len > len)
 		goto short_packet;
 	if (auth_len & 3)
 		goto inconsistent;
 	if (auth_len < 20 + 9 * 4)
 		goto auth_too_short;

 	/* We need to extract and decrypt the token and instantiate a session
 	 * key for it.  This bit, however, is application-specific.  If
 	 * possible, we use a default parser, but we might end up bumping this
 	 * to the app to deal with - which might mean a round trip to
 	 * userspace.
 	 */
 	ret = rxgk_extract_token(conn, skb, token_offset, token_len, &key);
 	if (ret < 0)
 		goto out;

 	/* We now have a key instantiated from the decrypted ticket.  We can
 	 * pass this to the application so that they can parse the ticket
 	 * content and we can use the session key it contains to derive the
 	 * keys we need.
 	 *
 	 * Note that we have to switch enctype at this point as the enctype of
 	 * the ticket doesn't necessarily match that of the transport.
 	 */
 	token = key->payload.data[0];
 	conn->security_level = token->rxgk->level;
 	conn->rxgk.start_time = __be64_to_cpu(rhdr.start_time);

 	gk = rxgk_generate_transport_key(conn, token->rxgk, sp->hdr.cksum, GFP_NOFS);
 	if (IS_ERR(gk)) {
 		ret = PTR_ERR(gk);
 		goto cant_get_token;
 	}

 	krb5 = gk->krb5;

 	trace_rxrpc_rx_response(conn, sp->hdr.serial, krb5->etype, sp->hdr.cksum, token_len);

 	/* Decrypt, parse and verify the authenticator. */
 	ret = rxgk_decrypt_skb(krb5, gk->resp_enc, skb,
 			       &auth_offset, &auth_len, &ec);
 	if (ret < 0) {
 		rxrpc_abort_conn(conn, skb, RXGK_SEALEDINCON, ret,
 				 rxgk_abort_resp_auth_dec);
 		goto out;
 	}

 	ret = rxgk_verify_authenticator(conn, krb5, skb, auth_offset, auth_len);
 	if (ret < 0)
 		goto out;

 	conn->key = key;
 	key = NULL;
 	ret = 0;
 out:
 	key_put(key);
 	_leave(" = %d", ret);
 	return ret;

 inconsistent:
 	ret = rxrpc_abort_conn(conn, skb, RXGK_INCONSISTENCY, -EPROTO,
 			       rxgk_abort_resp_xdr_align);
 	goto out;
 auth_too_short:
 	ret = rxrpc_abort_conn(conn, skb, RXGK_PACKETSHORT, -EPROTO,
 			       rxgk_abort_resp_short_auth);
 	goto out;
 short_packet:
 	ret = rxrpc_abort_conn(conn, skb, RXGK_PACKETSHORT, -EPROTO,
 			       rxgk_abort_resp_short_packet);
 	goto out;

 cant_get_token:
 	switch (ret) {
 	case -ENOMEM:
 		goto temporary_error;
 	case -EINVAL:
 		ret = rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EKEYREJECTED,
 				       rxgk_abort_resp_internal_error);
 		goto out;
 	case -ENOPKG:
 		ret = rxrpc_abort_conn(conn, skb, KRB5_PROG_KEYTYPE_NOSUPP,
 				       -EKEYREJECTED, rxgk_abort_resp_nopkg);
 		goto out;
 	}

 temporary_error:
 	/* Ignore the response packet if we got a temporary error such as
 	 * ENOMEM.  We just want to send the challenge again.  Note that we
 	 * also come out this way if the ticket decryption fails.
 	 */
 	goto out;
 }



